* {
    box-sizing: border-box;
}

body {
    font-family: system-ui, -apple-system, sans-serif;
    line-height: 1.6;
    color: var(--text-main);
    background-color: var(--bg-page);
    margin: 0;
    padding: 0;
}

.container {
    max-width: 800px;
    margin: 0 auto;
    padding: 0 2rem;
}

header {
    background-color: var(--bg-card);
    border-bottom: 1px solid var(--border);
    padding: 4rem 0;
    text-align: center;
    margin-bottom: 3rem;
}

header h1 {
    margin: 0;
    font-size: 2.5rem;
    font-weight: 800;
    letter-spacing: -0.025em;
}

header p {
    color: var(--text-muted);
    font-size: 1.125rem;
    margin-top: 0.5rem;
}

.example {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 0.75rem;
    margin-bottom: 1rem;
    overflow: hidden;
    transition: box-shadow 0.2s ease;
}

.example:hover {
    box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
}

.example h2 {
    margin: 0;
}

button {
    width: 100%;
    text-align: left;
    padding: 1.5rem;
    background: none;
    border: none;
    font-size: 1.25rem;
    font-weight: 600;
    color: var(--text-main);
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    transition: background-color 0.2s ease;
}

button:hover {
    background-color: #f1f5f9;
}

button:focus-visible {
    outline: 3px solid var(--focus-ring);
    outline-offset: -3px;
}

.icon {
    width: 1.25rem;
    height: 1.25rem;
    color: var(--text-muted);
    transition: transform 0.3s ease;
}

button[aria-expanded="true"] .icon {
    transform: rotate(180deg);
}

.details {
    padding: 0 1.5rem 1.5rem;
    color: var(--text-muted);
    font-size: 1.125rem;
}

.details[hidden] {
    display: none;
}

footer {
    padding: 4rem 0;
    text-align: center;
    color: var(--text-muted);
    font-size: 0.875rem;
}

@media (max-width: 640px) {
    header {
        padding: 2rem 0;
    }
    header h1 {
        font-size: 2rem;
    }
    button {
        padding: 1rem;
        font-size: 1.125rem;
    }
    .details {
        padding: 0 1rem 1rem;
    }
}
