+document.addEventListener('DOMContentLoaded', () => {
+    const disclosureButtons = document.querySelectorAll('.example h2 button');
+
+    disclosureButtons.forEach(button => {
+        // Find the panel associated with this button
+        // Requirement: container for controlled content has class "details"
+        // In our structure, it's the next sibling of the H2
+        const panel = button.closest('h2').nextElementSibling;
+
+        // Initialize state
+        // By default, we want them collapsed, but HTML has one expanded as a demo
+        // The skill says: Add hidden to collapsed panels via JavaScript at init, 
+        // not in the source HTML.
+        const isExpanded = button.getAttribute('aria-expanded') === 'true';
+        if (!isExpanded) {
+            panel.setAttribute('hidden', '');
+        }
+
+        button.addEventListener('click', () => {
+            const currentlyExpanded = button.getAttribute('aria-expanded') === 'true';
+            const newState = !currentlyExpanded;
+
+            button.setAttribute('aria-expanded', newState);
+            
+            if (newState) {
+                panel.removeAttribute('hidden');
+            } else {
+                panel.setAttribute('hidden', '');
+            }
+        });
+    });
+});
+
